	/** 
	 * jumpstart the process by instantiating2 Alert
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		alertId = AlertService.getAlertInstance()
		.createAlert( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AlertService.getAlertInstance()
				.createAlert( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.alertSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Alert : " + successValue.getAlertId());
							  if (successValue.getAlertId().equals(alertId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAlertList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Alert test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on alert consumed")
					);
			subscriber.alertSubscribe( alertId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Alert : " + successValue.getAlertId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAlertList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on alert for alertId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Alert. 
	 */
	protected Alert read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Alert" );

		Alert entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Alert with primary key" );
		msg.append( alertId );
		
		AlertFetchOneSummary fetchOneSummary = new AlertFetchOneSummary( alertId );

		try {
			entity = AlertService.getAlertInstance().getAlert( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Alert " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Alert.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Alert." );

		StringBuilder msg = new StringBuilder( "Failed to update a Alert : " );        
		Alert entity = read();
		UpdateAlertCommand command = generateUpdateCommand();
		command.setAlertId(entity.getAlertId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Alert." );

			// for use later on...
			alertId = entity.getAlertId();

			AlertService proxy = AlertService.getAlertInstance();  

			proxy.updateAlert( command ).get();

			LOGGER.info( "-- Successfully saved Alert - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + alertId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Alert.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Alert." );

		Alert entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Alert with id " + alertId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Alert with id " + alertId );

			throw e;
		}

		try{
			AlertService.getAlertInstance().delete( new DeleteAlertCommand( entity.getAlertId() ) ).get();
			LOGGER.info( "-- Successfully deleted Alert with id " + alertId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Alert with id " + alertId );

			throw e;
		}
	}

	/**
	 * get all Alerts.
	 */
	protected List<Alert> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Alerts:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Alert : " );        
		List<Alert> collection  = new ArrayList<>();

		try {
			// call the static get method on the AlertService
			collection = AlertService.getAlertInstance().getAllAlert();
			assertNotNull( collection, "An Empty collection of Alert was incorrectly returned.");
			
			// Now print out the values
			Alert entity = null;            
			Iterator<Alert> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAlertId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

